/*
 * engine3.c -- Q6651 / EXACT-D-3, seed-reachable exact experiment.
 * Parent engine: EXACT-D-2/engine2.c, blob
 * 2529cf4617e667800acc30b9d9179305c37c7031.
 * Include unchanged Q5630-literal.c and oracle.h from EXACT-D-2.
 *
 * Scheduler: iid uniform over e=0,...,2*n-1. Both halves run the literal
 * parent pair exactly once with coin=0. Only the query half may publish,
 * and only when parent_input_changed==0.
 *
 * The inherited policies P1/P16/PCLOCK/GLOBAL/NODRAIN are unchanged.
 * Added policies are QVg and QVg-NOVETO, 0<=g<=63. Their underlying
 * regional pass is P1: one unchanged outgoing-top query is one clean pass.
 * A clean illegal pass creates a current PENDING reject. After g further
 * clean passes it becomes the existing one-shot REJ terminal, which is
 * consumed on that same top->top+1 query service. QV0 therefore has the
 * same final detector bytes and transitions as P1 from the zero-detector
 * A/LETTER seeds. Every QV0 closure edge is checked against a P1 step.
 *
 * Source/cut edits reset the complete arc record before any detector work
 * on that service. Except in NOVETO, V=(row 22 or 23) with post-state
 * b a nonroot OUT/CLEAR fresh=1 resets every arc containing b. V is read
 * only from the returned row and the post-state served pair.
 *
 * Per-arc uint16 layout:
 *   bits 0..5  inherited mechanical phase;
 *   bit 6      inherited pass-clean tag;
 *   bit 7      current/qualified authority tag;
 *   bit 8      ready REJ terminal;
 *   bit 9      PENDING queued reject;
 *   bits 10..15 grace counter.
 * All fields are part of the exact state key.
 *
 * Seeds selected by --seed:
 *   A                 exact engine2 A_n seed;
 *   LETTER v          same parent bytes, every source letter v, 0<=v<6;
 *   REGEN6            n=6, root 0, all-4 word, one qualified PENDING
 *                     reject at top 5 for arc [2,5].
 * REGEN6 checks its literal arc is internally cut-free and illegal.
 *
 * Full rewards: E[D] and E[total current rooted births B_c]. Trial theta
 * is first native death or terminal entrance. The solver certifies b_g,
 * death probability, expected death-boundary stock P_g S, and the trial
 * residual b_g+P_g S-S for
 *   S = qualified PENDING/REJ records + illegal cut-free arcs.
 *
 * Rotation uses only the stabilizer of the immutable odd-top set. Every
 * stored Cell byte and detector byte participates in the key.
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <inttypes.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <float.h>
#include <limits.h>
#include <errno.h>
#include <fenv.h>
#include <sys/resource.h>
#include "Q5630-literal.c"
#include "oracle.h"
#ifdef __FAST_MATH__
#error "Certified residuals require a build without -ffast-math."
#endif
_Static_assert(CHAR_BIT==8 && sizeof(Cell)==24, "literal Cell layout changed");
_Static_assert(sizeof(uint16_t)==2 && sizeof(uint32_t)==4 && sizeof(uint64_t)==8,
               "integer layout");
_Static_assert(sizeof(double)==8 && FLT_RADIX==2 && DBL_MANT_DIG==53 &&
               DBL_MAX_EXP==1024, "binary64 storage required");
_Static_assert(LDBL_MANT_DIG>=DBL_MANT_DIG, "long double must contain double");
enum { E3_MAXN=8, E3_MAXA=4, E3_MAXKEY=200 };
enum { E3_P1=1, E3_P16, E3_PCLOCK, E3_GLOBAL, E3_NODRAIN, E3_QV };
enum { E3_PHASE=0x003f, E3_CLEAN=0x0040, E3_VALID=0x0080,
       E3_REJ=0x0100, E3_PENDING=0x0200,
       E3_GRACE_SHIFT=10, E3_GRACE_MASK=0xfc00 };
enum { E3_NONE=0, E3_UP, E3_TOP, E3_DOWN, E3_BOTTOM };
enum { E3_DEATH=1, E3_BCURRENT=2, E3_BUNCURRENT=4, E3_BROOTLESS=8 };
enum { E3_SEED_A=1, E3_SEED_LETTER, E3_SEED_REGEN6 };
typedef struct { Cell c[E3_MAXN]; uint16_t a[E3_MAXA]; } E3State;
typedef struct {
 int row,parent_row,changed,gap,birth,death;
 unsigned flags,edits,drains,cancelled,consumed,suppressed;
 unsigned vetoes,veto_cancelled,queued,grace_advanced,released;
} E3Step;
static int e3_n,e3_na,e3_degree,e3_policy,e3_base;
static int e3_grace,e3_noveto;
static int e3_seed_kind=E3_SEED_A,e3_seed_letter=-1;
static int e3_top[E3_MAXA],e3_index[E3_MAXN];
static int e3_rot[E3_MAXN],e3_nrot,e3_all_trials;
static size_t e3_keybytes;
static const char *e3_static_name(int p){switch(p){case E3_P1:return"P1";case E3_P16:return"P16";case E3_PCLOCK:return"PCLOCK";case E3_GLOBAL:return"GLOBAL";case E3_NODRAIN:return"NODRAIN";case E3_QV:return"QV";default:return"INVALID";}}
static const char *e3_policy_label(void){static char b[32];if(e3_policy==E3_QV)snprintf(b,sizeof b,"QV%d%s",e3_grace,e3_noveto?"-NOVETO":"");else snprintf(b,sizeof b,"%s",e3_static_name(e3_policy));return b;}
static const char *e3_seed_label(void){static char b[32];if(e3_seed_kind==E3_SEED_A)return"A_n";if(e3_seed_kind==E3_SEED_REGEN6)return"REGEN6";snprintf(b,sizeof b,"LETTER:%d",e3_seed_letter);return b;}
static int e3_static_policy_id(const char*s){for(int p=E3_P1;p<=E3_NODRAIN;p++)if(!strcmp(s,e3_static_name(p)))return p;return 0;}
static int e3_parse_policy(const char*s){int p=e3_static_policy_id(s);e3_grace=0;e3_noveto=0;if(p){e3_policy=p;e3_base=p<=E3_PCLOCK?p:E3_P16;return 1;}if(strncmp(s,"QV",2))return 0;const char*q=s+2;if(*q<'0'||*q>'9')return 0;unsigned long g=0;while(*q>='0'&&*q<='9'){g=10*g+(unsigned)(*q-'0');if(g>63)return 0;q++;}if(!strcmp(q,"-NOVETO"))e3_noveto=1;else if(*q)return 0;e3_policy=E3_QV;e3_base=E3_P1;e3_grace=(int)g;return 1;}
static void e3_geometry(int n){e3_n=n;e3_na=n/2;e3_degree=2*n;e3_keybytes=(size_t)n*sizeof(Cell)+2u*(size_t)e3_na;for(int i=0;i<n;i++)e3_index[i]=-1;for(int a=0;a<e3_na;a++){e3_top[a]=2*a+1;e3_index[e3_top[a]]=a;}e3_nrot=0;for(int r=0;r<n;r++){int ok=1;for(int a=0;a<e3_na;a++)if(e3_index[(e3_top[a]+r)%n]<0)ok=0;if(ok)e3_rot[e3_nrot++]=r;}}
static int e3_sym(const Cell*c){return 2*c->ad+c->mu;}
static int e3_roots(const Cell*c){int r=0;for(int i=0;i<e3_n;i++)r+=c[i].L;return r;}
static int e3_good(const Cell*c){int r=-1;for(int i=0;i<e3_n;i++)if(c[i].L){if(r>=0)return 0;r=i;}if(r<0)return 0;for(int k=0;k<e3_n;k++)if(!c[(r+k)%e3_n].rw||e3_sym(c+(r+k)%e3_n)!=ed_alpha_symbol((uint64_t)k))return 0;return 1;}
static int e3_site(int a,int q){return(e3_top[a]-3+q+e3_n)%e3_n;}
static uint16_t e3_signature(const Cell*c,int a){uint16_t z=0;for(int q=0;q<4;q++)z|=(uint16_t)((unsigned)e3_sym(c+e3_site(a,q))<<(3*q));for(int q=0;q<3;q++)z|=(uint16_t)((unsigned)!!effective_cut(c+e3_site(a,q),c+e3_site(a,q+1))<<(12+q));return z;}
static int e3_open(uint16_t s){return(s&0x7000u)==0;}
static int e3_bad(uint16_t s){unsigned char w[4];if(!e3_open(s))return 0;for(int q=0;q<4;q++)w[q]=(unsigned char)((s>>(3*q))&7u);return ed_illegal(w,4,ED_EXACT);}
static int e3_arc_contains(int a,int site){for(int q=0;q<4;q++)if(e3_site(a,q)==site)return 1;return 0;}
static unsigned e3_grace_get(uint16_t d){return(unsigned)((d&E3_GRACE_MASK)>>E3_GRACE_SHIFT);}
static void e3_grace_set(uint16_t*d,unsigned g){*d=(uint16_t)((*d&~E3_GRACE_MASK)|((g<<E3_GRACE_SHIFT)&E3_GRACE_MASK));}
static void e3_seed_base(E3State*s){memset(s,0,sizeof*s);for(int k=0;k<e3_n;k++){s->c[k].ad=s->c[k].result=AD_HASH;s->c[k].repair_prev=CR_NONE;s->c[k].h=h_none();s->c[k].phase=PH_IDLE;s->c[k].wt=k?WT_TODO:WT_D0;s->c[k].L=s->c[k].H=(uint8_t)!k;}}
static void e3_seed(E3State*s){e3_seed_base(s);if(e3_seed_kind==E3_SEED_LETTER){for(int k=0;k<e3_n;k++){s->c[k].ad=(uint8_t)(e3_seed_letter>>1);s->c[k].mu=(uint8_t)(e3_seed_letter&1);}}else if(e3_seed_kind==E3_SEED_REGEN6){for(int k=0;k<e3_n;k++){s->c[k].ad=AD_HASH;s->c[k].mu=0;}int a=e3_index[5];if(a>=0)s->a[a]=(uint16_t)(E3_PENDING|E3_VALID);}}
static int e3_seed_selfcheck(const E3State*s,int print){if(e3_roots(s->c)!=1||!s->c[0].L)return 0;if(e3_seed_kind==E3_SEED_REGEN6){if(e3_n!=6||e3_policy!=E3_QV||e3_index[5]<0)return 0;int a=e3_index[5];uint16_t sig=e3_signature(s->c,a);int sites=e3_site(a,0)==2&&e3_site(a,1)==3&&e3_site(a,2)==4&&e3_site(a,3)==5;int rec=s->a[a]==(E3_PENDING|E3_VALID);for(int b=0;b<e3_na;b++)if(b!=a&&s->a[b])rec=0;if(print)printf("SEED_SELF_CHECK seed=REGEN6 roots=1 root_site=0 arc_top=5 arc_sites=2,3,4,5 cut_free=%d illegal=%d pending_current=%d publication_receiver=0 receiver_root=%u\n",e3_open(sig),e3_bad(sig),rec,s->c[0].L);return sites&&e3_open(sig)&&e3_bad(sig)&&rec;}if(print)printf("SEED_SELF_CHECK seed=%s roots=1 root_site=0 source0=%d\n",e3_seed_label(),e3_sym(s->c));return 1;}
static void e3_invalidate(uint16_t*d){if(e3_policy==E3_NODRAIN)*d&=(uint16_t)~(E3_CLEAN|E3_VALID);else*d=0;}
static void e3_complete_legacy(uint16_t*d,uint16_t sig){int clean=!!(*d&E3_CLEAN);*d&=(uint16_t)~(E3_CLEAN|E3_VALID|E3_REJ);if(e3_bad(sig)&&(clean||e3_policy==E3_NODRAIN)){*d|=E3_REJ;if(clean)*d|=E3_VALID;}}
static void e3_counter_legacy(uint16_t*d,uint16_t sig){unsigned p=e3_base==E3_P1?1u:16u,q=*d&E3_PHASE;if(q==0){*d&=(uint16_t)~E3_CLEAN;if(e3_open(sig))*d|=E3_CLEAN;}++q;*d=(uint16_t)((*d&~E3_PHASE)|(q==p?0:q));if(q==p)e3_complete_legacy(d,sig);}
static int e3_clock_row(uint16_t*d,unsigned e){unsigned z=*d&E3_PHASE,ax=(z>>e)&1u,bx=(z>>(e+1))&1u;unsigned au=e==0?1u:((z>>(e+3))&1u),bu=e==2?0u:((z>>(e+4))&1u);int ev=E3_NONE;if(ax!=bx){z=(z&~(1u<<(e+1)))|(ax<<(e+1));if(e<2)z|=1u<<(e+4);ev=e==2?E3_TOP:E3_UP;}else if(au==1u&&bu==0u){if(e==0){z^=1u;ev=E3_BOTTOM;}else{z&=~(1u<<(e+3));ev=E3_DOWN;}}*d=(uint16_t)((*d&~E3_PHASE)|z);return ev;}
static int e3_privileges(unsigned z){int p=0;for(unsigned e=0;e<3;e++){uint16_t d=(uint16_t)z;p+=e3_clock_row(&d,e)!=E3_NONE;}return p;}
static int e3_clock_seed_phase(unsigned z){static const unsigned char p[12]={0x00,0x01,0x13,0x37,0x3f,0x1f,0x0f,0x0e,0x1c,0x38,0x30,0x10};for(int j=0;j<12;j++)if(z==p[j])return 1;return 0;}
static void e3_clock(uint16_t*d,unsigned edge,uint16_t sig){int unique=e3_privileges(*d&E3_PHASE)==1;int ev=e3_clock_row(d,edge);if(ev==E3_BOTTOM){*d&=(uint16_t)~E3_CLEAN;if(unique&&e3_open(sig))*d|=E3_CLEAN;}else if(ev==E3_TOP)e3_complete_legacy(d,sig);}
static void e3_qv_pass(uint16_t*d,uint16_t sig,E3Step*v,int a){unsigned q=*d&E3_PHASE;if(q==0){*d&=(uint16_t)~E3_CLEAN;if(e3_open(sig))*d|=E3_CLEAN;}++q;*d=(uint16_t)((*d&~E3_PHASE)|(q==1?0:q));if(q!=1)return;int clean=!!(*d&E3_CLEAN);*d&=(uint16_t)~E3_CLEAN;if(!clean){*d=0;return;}if(*d&E3_PENDING){if(!e3_bad(sig)){*d=0;return;}unsigned c=e3_grace_get(*d);if(e3_grace==0||c+1u>=(unsigned)e3_grace){*d&=(uint16_t)~(E3_PENDING|E3_GRACE_MASK);*d|=(uint16_t)(E3_REJ|E3_VALID);v->released|=1u<<a;}else{e3_grace_set(d,c+1u);v->grace_advanced|=1u<<a;}}else if(!(*d&E3_REJ)&&e3_bad(sig)){*d&=(uint16_t)~(E3_VALID|E3_REJ|E3_PENDING|E3_GRACE_MASK);if(e3_grace==0){*d|=(uint16_t)(E3_REJ|E3_VALID);v->released|=1u<<a;}else{*d|=(uint16_t)(E3_PENDING|E3_VALID);e3_grace_set(d,0);v->queued|=1u<<a;}}}
static int e3_is_v(int row,const Cell*b){return(row==22||row==23)&&!b->L&&b->h.dir==HD_OUT&&b->h.op==OP_CLEAR&&b->fresh==1;}
static void e3_record_edit(E3State*t,int a,E3Step*v){v->edits|=1u<<a;if(e3_policy!=E3_NODRAIN){v->drains|=1u<<a;if(t->a[a]&(E3_REJ|E3_PENDING))v->cancelled|=1u<<a;}e3_invalidate(t->a+a);}
static E3Step e3_step(const E3State*s,int e,E3State*t,int allow_birth){E3Step v;memset(&v,0,sizeof v);*t=*s;uint16_t before[E3_MAXA],after[E3_MAXA];int i=e%e3_n,j=(i+1)%e3_n,rb=e3_roots(s->c);for(int a=0;a<e3_na;a++)before[a]=e3_signature(s->c,a);v.parent_row=parent_pair_step(t->c+i,t->c+j,0,&v.changed);v.row=v.parent_row;v.gap=last_gap_defect;v.death=rb-e3_roots(t->c);if(v.death)v.flags|=E3_DEATH;for(int a=0;a<e3_na;a++){after[a]=e3_signature(t->c,a);if(before[a]!=after[a])e3_record_edit(t,a,&v);}if(e3_policy==E3_QV&&!e3_noveto&&e3_is_v(v.parent_row,t->c+j)){for(int a=0;a<e3_na;a++)if(e3_arc_contains(a,j)){v.vetoes|=1u<<a;if(t->a[a]&(E3_PENDING|E3_REJ))v.veto_cancelled|=1u<<a;t->a[a]=0;}}
 for(int a=0;a<e3_na;a++){if(e3_policy!=E3_NODRAIN&&((v.edits|v.vetoes)&(1u<<a)))continue;if(e3_policy==E3_QV){if(e>=e3_n&&!v.changed&&i==e3_top[a])e3_qv_pass(t->a+a,after[a],&v,a);}else if(e3_base==E3_PCLOCK){for(unsigned q=0;q<3;q++)if(i==e3_site(a,(int)q))e3_clock(t->a+a,q,after[a]);}else if(e>=e3_n&&!v.changed&&i==e3_top[a])e3_counter_legacy(t->a+a,after[a]);}
 int a=e3_index[i];if(e>=e3_n&&!v.changed&&a>=0&&(t->a[a]&E3_REJ)){int current=!!(t->a[a]&E3_VALID),roots=e3_roots(t->c);t->a[a]&=(uint16_t)~(E3_REJ|E3_VALID);v.consumed=1;if(allow_birth&&!t->c[j].L&&!(e3_policy==E3_GLOBAL&&roots>0)){cutauth_after_birth(t->c+i,t->c+j);v.birth=1;v.row=900;v.flags|=roots==0?E3_BROOTLESS:current?E3_BCURRENT:E3_BUNCURRENT;}else v.suppressed=1;}if(v.birth)for(int b=0;b<e3_na;b++)if(after[b]!=e3_signature(t->c,b))e3_record_edit(t,b,&v);return v;}
static int e3_core_step_equal(E3Step a,E3Step b){return a.row==b.row&&a.parent_row==b.parent_row&&a.changed==b.changed&&a.gap==b.gap&&a.birth==b.birth&&a.death==b.death&&a.flags==b.flags&&a.edits==b.edits&&a.drains==b.drains&&a.cancelled==b.cancelled&&a.consumed==b.consumed&&a.suppressed==b.suppressed;}
static E3Step e3_step_as_p1(const E3State*s,int e,E3State*t,int allow_birth){int p=e3_policy,b=e3_base,g=e3_grace,nv=e3_noveto;e3_policy=E3_P1;e3_base=E3_P1;e3_grace=0;e3_noveto=0;E3Step v=e3_step(s,e,t,allow_birth);e3_policy=p;e3_base=b;e3_grace=g;e3_noveto=nv;return v;}
static void e3_pack(const E3State*s,unsigned char*k){size_t z=(size_t)e3_n*sizeof(Cell);memcpy(k,s->c,z);for(int a=0;a<e3_na;a++){k[z++]=(unsigned char)s->a[a];k[z++]=(unsigned char)(s->a[a]>>8);}}
static void e3_unpack(const unsigned char*k,E3State*s){size_t z=(size_t)e3_n*sizeof(Cell);memset(s,0,sizeof*s);memcpy(s->c,k,z);for(int a=0;a<e3_na;a++){s->a[a]=(uint16_t)(k[z]|((uint16_t)k[z+1]<<8));z+=2;}}
static void e3_rotate(const E3State*s,int r,E3State*t){memset(t,0,sizeof*t);for(int i=0;i<e3_n;i++)t->c[i]=s->c[(i+r)%e3_n];for(int a=0;a<e3_na;a++)t->a[a]=s->a[e3_index[(e3_top[a]+r)%e3_n]];}
static void e3_canonical_key(const E3State*s,unsigned char*k){E3State t;unsigned char c[E3_MAXKEY];e3_pack(s,k);for(int z=1;z<e3_nrot;z++){e3_rotate(s,e3_rot[z],&t);e3_pack(&t,c);if(memcmp(c,k,e3_keybytes)<0)memcpy(k,c,e3_keybytes);}}
static unsigned e3_stock_value(const E3State*s){unsigned z=0;for(int a=0;a<e3_na;a++){uint16_t d=s->a[a];if((d&E3_VALID)&&(d&(E3_PENDING|E3_REJ)))z++;if(e3_bad(e3_signature(s->c,a)))z++;}return z;}
static uint32_t e3_N,e3_cap,e3_expanded,*e3_table,*e3_adj;static uint64_t e3_slots,e3_discovered_terminal;static unsigned char *e3_states,*e3_root,*e3_terminal,*e3_reward;static uint16_t*e3_stock;static struct timespec e3_started;static double e3_seconds=INFINITY;static const uint64_t e3_headroom=UINT64_C(64)*1048576;
static double e3_elapsed(void){struct timespec t;timespec_get(&t,TIME_UTC);return(double)(t.tv_sec-e3_started.tv_sec)+(double)(t.tv_nsec-e3_started.tv_nsec)/1e9;}
static void e3_resource(void){struct rusage r;if(!getrusage(RUSAGE_SELF,&r))printf("RESOURCE maxrss_native=%ld wall=%.3f\n",r.ru_maxrss,e3_elapsed());}
static void e3_fail(const char*r){e3_resource();printf("VERDICT UNKNOWN reason=%s states=%"PRIu32" expanded=%"PRIu32" terminals_discovered=%"PRIu64" wall=%.3f\n",r,e3_N,e3_expanded,e3_discovered_terminal,e3_elapsed());fflush(stdout);exit(3);}
static void e3_budget(void){if(e3_elapsed()>e3_seconds)e3_fail("wall-cap");}
static void*e3_alloc(size_t n,size_t z){if(z&&n>SIZE_MAX/z)e3_fail("size-overflow");void*p=calloc(n,z);if(!p)e3_fail("allocation-cap");return p;}
static void e3_hex(const unsigned char*p,size_t n){for(size_t i=0;i<n;i++)printf("%02x",(unsigned)p[i]);}
static void e3_show_state(const char*l,const E3State*s){unsigned char k[E3_MAXKEY];e3_pack(s,k);printf("%s roots=%d terminal=%d stock=%u key_bytes=%zu bytes=",l,e3_roots(s->c),e3_good(s->c),e3_stock_value(s),e3_keybytes);e3_hex(k,e3_keybytes);putchar('\n');for(int a=0;a<e3_na;a++)printf("ARC top=%d phase=%u pass_clean=%u valid=%u terminal=%s pending=%u grace=%u input_signature=%04x\n",e3_top[a],s->a[a]&E3_PHASE,!!(s->a[a]&E3_CLEAN),!!(s->a[a]&E3_VALID),s->a[a]&E3_REJ?"REJ":"EMPTY",!!(s->a[a]&E3_PENDING),e3_grace_get(s->a[a]),(unsigned)e3_signature(s->c,a));}
static void e3_instance(const char*r,uint32_t x,int e,const E3State*s,const E3State*t,E3Step v){printf("INSTANCE reason=%s state=%"PRIu32" service=%d edge=%d->%d slot=%s row=%d parent_row=%d changed=%d gap=%d birth=%d death=%d reward_flags=%u edits=%u drains=%u vetoes=%u\n",r,x,e,e%e3_n,(e%e3_n+1)%e3_n,e>=e3_n?"query":"physical",v.row,v.parent_row,v.changed,v.gap,v.birth,v.death,v.flags,v.edits,v.drains,v.vetoes);e3_show_state("BEFORE",s);e3_show_state("AFTER",t);e3_resource();printf("VERDICT INSTANCE scope=%s-reachable\n",e3_seed_label());exit(4);}
