static void e3_extreme(int net,int all,const double*m,const double*q,E3Cert c){uint32_t best=UINT32_MAX;uint64_t origins=0,cont=0;long double bp=-INFINITY,slo=-INFINITY,shi=-INFINITY;for(uint32_t x=0;x<e3_N;x++){if(e3_root[x]!=1||(!all&&e3_terminal[x]))continue;long double p,l,h;e3_trial_bounds(x,net,m,q,c,&p,&l,&h);origins++;if(best==UINT32_MAX||p>bp){best=x;bp=p;}if(l>slo)slo=l;if(h>shi)shi=h;}const char*scope=all?"all-one-root":"nonterminal-one-root";if(best==UINT32_MAX){printf("SUP scope=%s metric=%s origins=0 value=UNDEFINED\n",scope,net?"net":"b_g");return;}long double p,bl,bu,other=-INFINITY;e3_trial_bounds(best,net,m,q,c,&p,&bl,&bu);for(uint32_t x=0;x<e3_N;x++){if(e3_root[x]!=1||(!all&&e3_terminal[x]))continue;long double xp,xl,xu;e3_trial_bounds(x,net,m,q,c,&xp,&xl,&xu);if(xu>=slo)cont++;if(x!=best&&xu>other)other=xu;}const char*st=bl>other?"certified-unique":bl>=other?"certified-maximizer":"unresolved-candidate";long double regret=fmaxl(0,e3_up(shi-bl));printf("SUP scope=%s metric=%s origins=%"PRIu64" estimate=%.21Lg lower=%.21Lg upper=%.21Lg candidate_id=%"PRIu32" argmax_status=%s contenders=%"PRIu64" candidate_regret_bound=%.12Lg\n",scope,net?"net":"b_g",origins,bp,slo,shi,best,st,cont,regret);printf("ARGMAX scope=%s metric=%s id=%"PRIu32" terminal=%u stock=%u key_bytes=%zu bytes=",scope,net?"net":"b_g",best,e3_terminal[best],e3_stock[best],e3_keybytes);e3_hex(e3_states+(size_t)best*e3_keybytes,e3_keybytes);putchar('\n');}
