static void e3_solve(double tol,uint64_t maxit){e3_absorption();double*D=e3_alloc(e3_N,sizeof*D),*F=e3_alloc(e3_N,sizeof*F),*h=e3_alloc(e3_N,sizeof*h),*m=e3_alloc(e3_N,sizeof*m),*q=e3_alloc(e3_N,sizeof*q),*ps=e3_alloc(e3_N,sizeof*ps);E3Cert c={INFINITY,INFINITY,0,0,0,0,0,INFINITY,INFINITY,INFINITY,INFINITY,INFINITY,INFINITY,INFINITY};uint64_t done=0;int cert=0;for(uint64_t it=1;it<=maxit;it++){for(uint32_t x=0;x<e3_N;x++)if(!e3_terminal[x]){long double sd=0,sf=0,sh=0,sm=0,sq=0,sp=0;for(int e=0;e<e3_degree;e++){size_t k=(size_t)x*e3_degree+e;uint32_t y=e3_adj[k];int de=!!(e3_reward[k]&E3_DEATH),bc=!!(e3_reward[k]&E3_BCURRENT),go=!de&&!e3_terminal[y];sd+=(long double)D[y]+de;sf+=(long double)F[y]+bc;sh+=(long double)h[y];sm+=(long double)bc+(go?(long double)m[y]:0);sq+=(long double)de+(go?(long double)q[y]:0);sp+=(long double)(de?e3_stock[y]:0)+(go?(long double)ps[y]:0);}D[x]=(double)(sd/e3_degree);F[x]=(double)(sf/e3_degree);h[x]=(double)(1+sh/e3_degree);m[x]=(double)(sm/e3_degree);q[x]=(double)(sq/e3_degree);ps[x]=(double)(sp/e3_degree);}done=it;e3_budget();if(it%100==0||it==maxit){c=e3_certify(D,F,h,m,q,ps);printf("VI iterations=%"PRIu64" seed_D=%.17g seed_Bc=%.17g seed_b_g=%.17g seed_q=%.17g seed_PS=%.17g error_D=%.9Lg error_Bc=%.9Lg error_b=%.9Lg error_q=%.9Lg error_PS=%.9Lg error_residual=%.9Lg gap=%.9Lg T_bound=%.9Lg wall=%.3f\n",it,D[0],F[0],m[0],q[0],ps[0],c.eD,c.eF,c.eM,c.eQ,c.eP,c.eResidual,c.gap,c.T,e3_elapsed());if(e3_cert_ok(c,tol)){cert=1;break;}}}if(!cert){printf("VI_LAST iterations=%"PRIu64" certified=0\n",done);e3_fail("VI-iteration-cap");}printf("CERTIFICATE gap=%.21Lg max_T_bound=%.21Lg residual_D=%.12Lg residual_Bc=%.12Lg residual_b=%.12Lg residual_q=%.12Lg residual_PS=%.12Lg error_D=%.12Lg error_Bc=%.12Lg error_b=%.12Lg error_q=%.12Lg error_PS=%.12Lg error_net=%.12Lg error_stock_residual=%.12Lg\n",c.gap,c.T,c.rD,c.rF,c.rM,c.rQ,c.rP,c.eD,c.eF,c.eM,c.eQ,c.eP,c.eNet,c.eResidual);long double Dlo=fmaxl(0,e3_down((long double)D[0]-c.eD)),Dhi=e3_up((long double)D[0]+c.eD),Flo=fmaxl(0,e3_down((long double)F[0]-c.eF)),Fhi=e3_up((long double)F[0]+c.eF);printf("EXPECT n=%d policy=%s seed=%s states=%"PRIu32" iterations=%"PRIu64" E_D=%.17g E_D_lo=%.21Lg E_D_hi=%.21Lg E_Bc=%.17g E_Bc_lo=%.21Lg E_Bc_hi=%.21Lg numerical_method=GS-outward-residual\n",e3_n,e3_policy_label(),e3_seed_label(),e3_N,done,D[0],Dlo,Dhi,F[0],Flo,Fhi);long double bp,bl,bh,np,nl,nh,rp,rl,rh;e3_trial_bounds(0,0,m,q,c,&bp,&bl,&bh);e3_trial_bounds(0,1,m,q,c,&np,&nl,&nh);e3_stock_residual_bounds(0,m,ps,c,&rp,&rl,&rh);long double qlo=fmaxl(0,e3_down((long double)q[0]-c.eQ)),qhi=fminl(1,e3_up((long double)q[0]+c.eQ)),plo=fmaxl(0,e3_down((long double)ps[0]-c.eP)),phi=e3_up((long double)ps[0]+c.eP);printf("SEED_TRIAL stock=%u b_g=%.21Lg b_lo=%.21Lg b_hi=%.21Lg death_prob=%.17g death_lo=%.21Lg death_hi=%.21Lg P_g_S=%.17g P_g_S_lo=%.21Lg P_g_S_hi=%.21Lg net=%.21Lg net_lo=%.21Lg net_hi=%.21Lg stock_residual=%.21Lg residual_lo=%.21Lg residual_hi=%.21Lg\n",e3_stock[0],bp,bl,bh,q[0],qlo,qhi,ps[0],plo,phi,np,nl,nh,rp,rl,rh);uint64_t nt=0,tt=0;for(uint32_t x=0;x<e3_N;x++)if(e3_root[x]==1){if(e3_terminal[x])tt++;else nt++;}printf("TRIAL_DOMAIN nonterminal_one_root=%"PRIu64" terminal_one_root=%"PRIu64" theta=first-native-death-or-terminal continuation_may_have_multiple_roots=1\n",nt,tt);e3_extreme(0,0,m,q,c);e3_extreme(1,0,m,q,c);e3_extreme(0,1,m,q,c);e3_extreme(1,1,m,q,c);e3_stock_extreme(0,m,ps,c);e3_stock_extreme(1,m,ps,c);if(e3_all_trials)e3_print_all_trials(m,q,ps,c);free(D);free(F);free(h);free(m);free(q);free(ps);}
