static void e3_random_state(E3State*s){memset(s,0,sizeof*s);for(int i=0;i<e3_n;i++){Cell*c=s->c+i;c->L=(uint8_t)(e3_random()%4==0);c->B=(uint8_t)(e3_random()%3);c->H=(uint8_t)(e3_random()%2);c->S=(uint8_t)(e3_random()%2);c->e=(uint8_t)(e3_random()%2);c->mu=(uint8_t)(e3_random()%2);c->w=(uint8_t)(e3_random()%2);c->rw=(uint8_t)(e3_random()%2);c->fresh=(uint8_t)(e3_random()%2);c->ad=(uint8_t)(e3_random()%3);c->wt=(uint8_t)(e3_random()%5);c->nb=(uint8_t)(e3_random()%4);c->cb=(uint8_t)(e3_random()%4);c->rb=(uint8_t)(e3_random()%2);c->fu=(uint8_t)(e3_random()%2);c->phase=(uint8_t)(e3_random()%PH_COUNT);c->par=(uint8_t)(e3_random()%2);c->final=(uint8_t)(e3_random()%2);c->result=(uint8_t)(e3_random()%3);c->h.dir=(uint8_t)(e3_random()%4);c->h.op=(uint8_t)(e3_random()%OP_COUNT);c->h.acc=(uint8_t)(e3_random()%64);c->repair_pending=(uint8_t)(e3_random()%8==0);c->repair_prev=(uint8_t)(e3_random()%7);}for(int a=0;a<e3_na;a++){if(e3_policy==E3_QV){unsigned z=(unsigned)(e3_random()%3);if(z==1){s->a[a]=(uint16_t)(E3_PENDING|E3_VALID);unsigned mm=e3_grace?(unsigned)e3_grace:1u;e3_grace_set(s->a+a,(unsigned)(e3_random()%mm));}else if(z==2)s->a[a]=(uint16_t)(E3_REJ|((e3_random()&1u)?E3_VALID:0));}else{unsigned mod=e3_base==E3_PCLOCK?64u:e3_base==E3_P1?1u:16u;s->a[a]=(uint16_t)(e3_random()%mod);if(e3_random()&1u)s->a[a]|=E3_CLEAN;if(e3_random()&1u){s->a[a]|=E3_REJ;if(e3_random()&1u)s->a[a]|=E3_VALID;}}}}
static int e3_validate_qv0(void){if(e3_policy!=E3_QV||e3_grace!=0||e3_seed_kind==E3_SEED_REGEN6)return 0;uint64_t steps=0;e3_rng=UINT64_C(0x6651a0b0c0d0);for(int tr=0;tr<100;tr++){E3State q,p;e3_seed(&q);p=q;for(int k=0;k<100;k++){int e=(int)(e3_random()%(unsigned)e3_degree);E3State qt,pt;E3Step a=e3_step(&q,e,&qt,1),b=e3_step_as_p1(&p,e,&pt,1);unsigned char x[E3_MAXKEY],y[E3_MAXKEY];e3_pack(&qt,x);e3_pack(&pt,y);if(memcmp(x,y,e3_keybytes)||!e3_core_step_equal(a,b)){printf("VALIDATION_FAILURE kind=QV0-P1-seed-replay trajectory=%d step=%d service=%d\n",tr,k,e);return 1;}q=qt;p=pt;steps++;}}printf("QV0_REPLAY seed=%s random_steps=%"PRIu64" byte_mismatches=0 transition_mismatches=0\n",e3_seed_label(),steps);return 0;}
static int e3_validate(void){E3State seed;e3_seed(&seed);if(!e3_seed_selfcheck(&seed,1)){puts("VALIDATION_FAILURE kind=seed-self-check");return 1;}if(e3_validate_qv0())return 1;uint64_t steps=0,rots=0,gaps=0;e3_rng=UINT64_C(0x6452c4a12345);for(int tr=0;tr<100;tr++){E3State s;Cell direct[E3_MAXN];e3_random_state(&s);memcpy(direct,s.c,(size_t)e3_n*sizeof(Cell));for(int k=0;k<100;k++){E3State t;int e=(int)(e3_random()%(unsigned)e3_degree);E3Step v=e3_step(&s,e,&t,0);int i=e%e3_n,j=(i+1)%e3_n,ch=0,rb=e3_roots(direct);int row=parent_pair_step(direct+i,direct+j,0,&ch),gap=last_gap_defect,de=rb-e3_roots(direct);if(v.row!=row||v.parent_row!=row||v.changed!=ch||v.gap!=gap||v.birth!=0||v.death!=de||(v.flags&(E3_BCURRENT|E3_BUNCURRENT|E3_BROOTLESS))||e3_roots(t.c)!=rb-de||memcmp(t.c,direct,(size_t)e3_n*sizeof(Cell))){printf("VALIDATION_FAILURE step=%"PRIu64" service=%d row=%d/%d changed=%d/%d gap=%d/%d death=%d/%d\n",steps,e,v.row,row,v.changed,ch,v.gap,gap,v.death,de);return 1;}gaps+=!!gap;for(int z=1;z<e3_nrot;z++){int r=e3_rot[z],re=(i-r+e3_n)%e3_n+(e/e3_n)*e3_n;E3State rs,rt,want;unsigned char ka[E3_MAXKEY],kb[E3_MAXKEY];e3_rotate(&s,r,&rs);E3Step rv=e3_step(&rs,re,&rt,0);e3_rotate(&t,r,&want);e3_pack(&rt,ka);e3_pack(&want,kb);if(rv.row!=v.row||rv.parent_row!=v.parent_row||rv.changed!=v.changed||rv.gap!=v.gap||rv.birth!=v.birth||rv.death!=v.death||rv.flags!=v.flags||memcmp(ka,kb,e3_keybytes)){printf("VALIDATION_FAILURE kind=rotation step=%"PRIu64" shift=%d service=%d mapped_service=%d\n",steps,r,e,re);return 1;}rots++;}s=t;steps++;}}printf("VALIDATE n=%d policy=%s seed=%s random_steps=%"PRIu64" trajectories=100 services_per_trajectory=100 cell_bytes_per_step=%zu oracle_callbacks=0 byte_mismatches=0 row_mismatches=0 change_mismatches=0 death_mismatches=0 gap_mismatches=0 parent_gap_reports=%"PRIu64" rotation_checks=%"PRIu64" rotation_mismatches=0\n",e3_n,e3_policy_label(),e3_seed_label(),steps,(size_t)e3_n*sizeof(Cell),gaps,rots);return 0;}
static void e3_usage(void){fputs("usage:\n  engine3 --preflight\n  engine3 --validate n POLICY [--seed A|REGEN6|LETTER v]\n  engine3 n POLICY cap MiB seconds [tolerance [max_iterations]] [--base P1|P16|PCLOCK] [--seed A|REGEN6|LETTER v] [--all-trials]\nPOLICY=P1|P16|PCLOCK|GLOBAL|NODRAIN|QVg|QVg-NOVETO, 0<=g<=63.\n",stderr);exit(2);}
static uint64_t e3_parse_u64(const char*s){if(!s||*s<'0'||*s>'9')e3_usage();char*e;errno=0;unsigned long long u=strtoull(s,&e,10);if(errno||*e||u>UINT64_MAX)e3_usage();return(uint64_t)u;}
static double e3_parse_double(const char*s){char*e;errno=0;double v=strtod(s,&e);if(errno||e==s||*e||!isfinite(v))e3_usage();return v;}
static int e3_base_arg(const char*s){int b=e3_static_policy_id(s);if(b<E3_P1||b>E3_PCLOCK)e3_usage();return b;}
static void e3_seed_option(int argc,char**argv,int*i){if(*i>=argc)e3_usage();const char*s=argv[(*i)++];if(!strcmp(s,"A")){e3_seed_kind=E3_SEED_A;e3_seed_letter=-1;return;}if(!strcmp(s,"REGEN6")){e3_seed_kind=E3_SEED_REGEN6;e3_seed_letter=-1;return;}if(!strcmp(s,"LETTER")){if(*i>=argc)e3_usage();uint64_t v=e3_parse_u64(argv[(*i)++]);if(v>5)e3_usage();e3_seed_kind=E3_SEED_LETTER;e3_seed_letter=(int)v;return;}e3_usage();}
static void e3_options(int argc,char**argv,int i,int all){while(i<argc){if(!strcmp(argv[i],"--base")&&i+1<argc){if(e3_policy<E3_GLOBAL||e3_policy==E3_QV)e3_usage();e3_base=e3_base_arg(argv[i+1]);i+=2;}else if(!strcmp(argv[i],"--seed")){i++;e3_seed_option(argc,argv,&i);}else if(all&&!strcmp(argv[i],"--all-trials")){e3_all_trials=1;i++;}else e3_usage();}}
int main(int argc,char**argv){timespec_get(&e3_started,TIME_UTC);setvbuf(stdout,NULL,_IOLBF,0);if(argc<2)e3_usage();if(!strcmp(argv[1],"--preflight")){if(argc!=2)e3_usage();e3_preflight();return 0;}if(sizeof(size_t)<8)return 2;if(fesetround(FE_TONEAREST)||fegetround()!=FE_TONEAREST)return 2;K=2;cutauth_control=0;if(!strcmp(argv[1],"--validate")){if(argc<4)e3_usage();uint64_t nn=e3_parse_u64(argv[2]);if(nn<4||nn>8)e3_usage();e3_geometry((int)nn);if(!e3_parse_policy(argv[3]))e3_usage();e3_options(argc,argv,4,0);if(e3_seed_kind==E3_SEED_REGEN6&&(e3_n!=6||e3_policy!=E3_QV))e3_usage();ed_oracle_init(4);return e3_validate();}if(argc<6)e3_usage();uint64_t nn=e3_parse_u64(argv[1]),cap=e3_parse_u64(argv[3]),mib=e3_parse_u64(argv[4]);if(nn<4||nn>8||cap<1||cap>UINT64_C(1000000000)||!mib||mib>UINT64_MAX/1048576)e3_usage();e3_geometry((int)nn);e3_cap=(uint32_t)cap;if(!e3_parse_policy(argv[2]))e3_usage();e3_seconds=e3_parse_double(argv[5]);if(e3_seconds<=0)e3_usage();double tol=1e-7;uint64_t maxit=UINT64_C(1000000);int i=6;if(i<argc&&strncmp(argv[i],"--",2))tol=e3_parse_double(argv[i++]);if(i<argc&&strncmp(argv[i],"--",2))maxit=e3_parse_u64(argv[i++]);if(tol<=0||!maxit||maxit==UINT64_MAX)e3_usage();e3_options(argc,argv,i,1);if(e3_seed_kind==E3_SEED_REGEN6&&(e3_n!=6||e3_policy!=E3_QV))e3_usage();uint64_t limbytes=mib*1048576,peak=e3_peak_bytes(e3_cap);e3_slots=e3_slots_for(e3_cap);printf("DOMAIN n=%d policy=%s seed=%s cap=%"PRIu32" MiB=%"PRIu64" degree=%d key_bytes=%zu estimated_peak_bytes=%"PRIu64" hash_slots=%"PRIu64" scheduler=iid-2n-uniform quotient=top-set-stabilizer\n",e3_n,e3_policy_label(),e3_seed_label(),e3_cap,mib,e3_degree,e3_keybytes,peak,e3_slots);if(peak>limbytes)e3_fail("memory-preflight");rlim_t l=(rlim_t)limbytes;struct rlimit as={l,l},core={0,0};if(setrlimit(RLIMIT_AS,&as)||setrlimit(RLIMIT_CORE,&core))return 2;ed_oracle_init(4);e3_build_graph();e3_solve(tol,maxit);e3_resource();printf("VERDICT CLOSED exact_seed_graph expectations=numerical-certified-tolerance scope=%s-only\n",e3_seed_label());return 0;}
